Q: How to safely pass credentials from n8n to browserless puppeteer script? A: <p>Credentials can be passed through Generic Credential Type - Custom auth with a very specific JSON structure:</p>
<pre class="lang-json prettyprint-override"><code>{
  &quot;qs&quot;: {
    &quot;token&quot;: &quot;BROWSERLESS_TOKEN&quot;
  },
  &quot;body&quot;: {
    &quot;context&quot;: {
      &quot;username&quot;: &quot;USERNAME&quot;,
      &quot;password&quot;: &quot;PASSWORD&quot;
    }
  }
}
</code></pre>
<p>Both <code>body</code> and <code>context</code> must be present, then both work at the same time:</p>
<ul>
<li><p>browserless is authenticated with the token</p>
</li>
<li><p>credentials are injected in the context object passed to the script</p>
</li>
</ul>

Q: Angular 21 - Variable change not rendered in DOM A: <p>When the variables are not updating as expected in Angular 21.</p>
<p>We can immediately assume the problem might be zoneless change detection.</p>
<p>The solution when using zoneless, is to use <code>signals</code> for each property in the component. The value changes on the signals will trigger change detection on the particular DOM and view is refreshed.</p>
<p>Change detection fires only when necessary, so we get a performance boost.</p>
<p>Converting the components to signals:</p>
<h3>Home Page TS:</h3>
<pre><code>export class HomePage {
  loading = signal&lt;boolean&gt;(false);

  @ViewChild(WaitingScreenComponent) waitingScreen!: WaitingScreenComponent;

  constructor() {
    this.displayWaitingScreen();
  }

  displayWaitingScreen() {
    this.loading.set(true);

    of(true)
      .pipe(delay(2000))
      .subscribe(() =&gt; {
        console.log('Simulate Countdown Launch');
        this.waitingScreen.startCountdown();
      });
  }

  handleCountdownFinished() {
    this.loading.set(false);
  }
}
</code></pre>
<h3>Home Page HTML:</h3>
<pre><code>&lt;ion-header [translucent]=&quot;true&quot;&gt;
  &lt;ion-toolbar&gt;
    &lt;ion-title&gt;Home Page&lt;/ion-title&gt;
  &lt;/ion-toolbar&gt;
&lt;/ion-header&gt;

&lt;ion-content fullscreen=&quot;false&quot;&gt;
  @if(loading()){
  &lt;app-waiting-screen (onCountdownFinished)=&quot;handleCountdownFinished()&quot;&gt;
  &lt;/app-waiting-screen&gt;
  }@else{
  &lt;ion-card (click)=&quot;displayWaitingScreen()&quot;&gt;
    &lt;ion-card-content&gt;
      &lt;div&gt;Display Waiting Screen&lt;/div&gt;
    &lt;/ion-card-content&gt;
  &lt;/ion-card&gt;
  }
&lt;/ion-content&gt;
</code></pre>
<h3>Waiting Screen HTML:</h3>
<pre><code>&lt;div class=&quot;loading-overlay&quot;&gt;
  &lt;div class=&quot;song-info-card&quot;&gt;
    &lt;h2&gt;Title&lt;/h2&gt;
    &lt;h4&gt;artist&lt;/h4&gt;

    &lt;ion-spinner name=&quot;bubbles&quot;&gt;&lt;/ion-spinner&gt;
    @let countdownVal = countdown(); @if (countdownVal !== null) {
    &lt;div class=&quot;countdown&quot;&gt;{{ countdownVal }}&lt;/div&gt;
    }@else{
    &lt;p class=&quot;loading-message&quot;&gt;Loading music ...&lt;/p&gt;
    }
  &lt;/div&gt;
&lt;/div&gt;
</code></pre>
<h3>Waiting Screen TS:</h3>
<pre><code>export class WaitingScreenComponent {
  countdown = signal&lt;number | null&gt;(null);
  onCountdownFinished = output();

  constructor() {}

  startCountdown() {
    this.countdown.set(3);
    console.log(this.countdown);
    const interval = setInterval(() =&gt; {
      this.countdown.update((prev: number | null) =&gt; (prev || 0) - 1);
      console.log(this.countdown);
      if (this.countdown() === 0) {
        clearInterval(interval);
        setTimeout(() =&gt; {
          this.onCountdownFinished.emit();
          console.log('Finished');
        }, 500);
      }
    }, 1000);
  }
}
</code></pre>
<h3><a href="https://stackblitz.com/edit/angular-21dwoyyj" rel="nofollow noreferrer">Stackblitz Demo</a></h3>
<hr />
<p>If you do not want to use zoneless. Then add the below two items and Angular will work as usual using zone based change detection.</p>
<pre><code>import 'zone.js';
import { bootstrapApplication } from '@angular/platform-browser';
...

bootstrapApplication(AppComponent, {
  providers: [
    ...
    provideZoneChangeDetection({ eventCoalescing: true }),
  ],
});
</code></pre>
<h3><a href="https://stackblitz.com/edit/angular-hcmpbcf5" rel="nofollow noreferrer">Stackblitz Demo</a></h3>

Q: How can I output a PSCustomObject from a compiled Cmdlet? A: <p>If you wanted to imitate what PowerShell does with the <code>[pscustomobject]</code> type accelerator, as noted in my other answer, you could do it via AST parsing. However this would only work if the cmdlet is called passing in a hash table literal... If its constructed beforehand and the variable is passed as argument then it fails. This isn't precisely a robust solution but is more so as demonstration to get an idea what the engine does behind the scenes. This solution <strong>does ensure ordering of properties</strong>.</p>
<p>The reflection to get the <code>.Text</code> value from <code>IScriptExtent</code> is only needed if you're targeting <code>PowerShellStandard.Library</code>; if you're targeting <code>System.Management.Automation</code> or <code>Microsoft.PowerShell.SDK</code> &gt;= <code>7.4</code>, then you can get it from <a href="https://learn.microsoft.com/en-us/dotnet/api/system.management.automation.invocationinfo.statement?view=powershellsdk-7.4.0#system-management-automation-invocationinfo-statement" rel="nofollow noreferrer"><code>MyInvocation.Statement</code></a>.</p>
<pre class="lang-cs prettyprint-override"><code>using System;
using System.Collections;
using System.Management.Automation;
using System.Management.Automation.Language;
using System.Reflection;

[Cmdlet(VerbsData.Out, &quot;PsCustomObject&quot;)]
public class OutPsCustomObjectCommand : PSCmdlet
{
    private static readonly Func&lt;InvocationInfo, IScriptExtent&gt; s_getExtent;

    // should only be used in the cmdlet's context methods
    private string Statement { get =&gt; s_getExtent(MyInvocation).Text; }

    // technically not using this but needed for positional binding
    [Parameter(Position = 0, Mandatory = true)]
    public Hashtable? Hashtable { get; set; }

    static OutPsCustomObjectCommand()
    {
        s_getExtent = (Func&lt;InvocationInfo, IScriptExtent&gt;)typeof(InvocationInfo)
            .GetProperty(&quot;ScriptPosition&quot;, BindingFlags.Instance | BindingFlags.NonPublic)
            .GetMethod.CreateDelegate(typeof(Func&lt;InvocationInfo, IScriptExtent&gt;));
    }

    protected override void EndProcessing()
    {
        HashtableAst ast = (HashtableAst)Parser
            .ParseInput(Statement, out _, out _)
            .Find(e =&gt; e is HashtableAst, false);

        PSObject output = new();
        foreach ((ExpressionAst exp, StatementAst statement) in ast.KeyValuePairs)
        {
            output.Properties.Add(new PSNoteProperty(
                exp.ToString(), statement.SafeGetValue()));
        }

        WriteObject(output);
    }
}
</code></pre>
